    "serve": {
      "executor": "@angular-devkit/build-angular:dev-server",
      "configurations": {
        "production": {
          "buildTarget": "startuphafen-frontend:build:production",
          "disableHostCheck": true
        },
        "development": {
          "host": "0.0.0.0",
          "port": 4201,
          "disableHostCheck": true,
          "buildTarget": "startuphafen-frontend:build:development"
        }
      },
      "defaultConfiguration": "development"
    },
    "extract-i18n": {
      "executor": "@angular-devkit/build-angular:extract-i18n",
      "options": {
        "buildTarget": "startuphafen-frontend:build"
      }
    },
    "lint": {
      "executor": "@nx/eslint:lint"
    },
    "test": {
      "executor": "@nx/jest:jest",
      "outputs": ["{workspaceRoot}/coverage/{projectRoot}"],
      "options": {
        "jestConfig": "apps/startuphafen-frontend/jest.config.ts"
      }
    },
    "serve-static": {
      "executor": "@nx/web:file-server",
      "options": {
        "buildTarget": "startuphafen-frontend:build"
      }
    },
    "typecheck": {
      "executor": "nx:run-commands",
      "options": {
        "cwd": "apps/startuphafen-frontend",
        "commands": [
          "tsc -p tsconfig.app.json --noEmit && tsc -p tsconfig.spec.json --noEmit"
        ]
      }
    },
    "doc": {
      "executor": "@startuphafen/pct-pipeline:doc-builder",
      "options": {
        "app": "startuphafen-frontend"
      }
    }
  }
